// Memory-Mapped Peripheral Register Access
#define GPIOA_BASE 0x40020000UL
#define GPIOA_ODR  (*(volatile uint32_t *)(GPIOA_BASE + 0x14))

void toggle_led(void) {
    GPIOA_ODR ^= (1U << 5); // Toggle Pin 5
}

// Interrupt Service Routine (ISR) in ARM Cortex-M
void EXTI0_IRQHandler(void) {
    if (EXTI->PR & (1 << 0)) {
        EXTI->PR = (1 << 0); // Clear interrupt flag
        handle_button_press();
    }
}

// I2C Sensor Read Transaction
uint8_t read_sensor(uint8_t dev_addr, uint8_t reg) {
    i2c_start();
    i2c_write(dev_addr << 1);
    i2c_write(reg);
    i2c_start(); // Repeated start
    i2c_write((dev_addr << 1) | 1);
    uint8_t val = i2c_read_nack();
    i2c_stop();
    return val;
}

// FreeRTOS Task Spawning
void SensorTask(void *pvParameters) {
    for (;;) {
        read_adc_values();
        vTaskDelay(pdMS_TO_TICKS(100));
    }
}
